/**
 * AllDataTypes DataPills Validation - Part 10 of 11
 *
 * This file contains 15 ServiceNow datatypes for validation testing.
 * Each datatype is defined as a subflow input and referenced in a log action
 * to validate datapill functionality across all supported types.
 *
 * Datatypes in this part: timer, translated, translated_field, translated_html, translated_text...
 */

import { Subflow, wfa, action } from '@servicenow/sdk/automation'
import {
    GenericColumn,
    JsonColumn,
    TranslatedFieldColumn,
    TranslatedTextColumn,
    UrlColumn,
    UserRolesColumn,
    VersionColumn,
} from '@servicenow/sdk/core'

export const alldatatypesvalidationPart10 = Subflow(
    {
        $id: Now.ID['301a85f3ebc54fd2becdfa2163d06c69'],
        name: 'AllDatatypesValidation_Part10',
        description: 'Comprehensive test subflow with ServiceNow datatypes - Part 10 of 11',
        runAs: 'user',
        inputs: {
            timer: GenericColumn({
                label: 'timer',
                maxLength: 65000,
                columnType: 'timer',
            }),
            translated: GenericColumn({
                label: 'translated',
                maxLength: 65000,
                columnType: 'translated',
            }),
            translated_field: TranslatedFieldColumn({
                label: 'translated_field',
                maxLength: 65000,
            }),
            translated_html: GenericColumn({
                label: 'translated_html',
                maxLength: 65000,
                columnType: 'translated_html',
            }),
            translated_text: TranslatedTextColumn({
                label: 'translated_text',
                maxLength: 65000,
            }),
            tree_code: GenericColumn({
                label: 'tree_code',
                maxLength: 65000,
                columnType: 'tree_code',
            }),
            tree_path: GenericColumn({
                label: 'tree_path',
                maxLength: 65000,
                columnType: 'tree_path',
            }),
            url: UrlColumn({
                label: 'url',
                maxLength: 65000,
            }),
            user_image: GenericColumn({
                label: 'user_image',
                maxLength: 65000,
                columnType: 'user_image',
            }),
            user_input: GenericColumn({
                label: 'user_input',
                maxLength: 65000,
                columnType: 'user_input',
            }),
            user_roles: UserRolesColumn({
                label: 'user_roles',
                maxLength: 65000,
            }),
            variable_conditions: GenericColumn({
                label: 'variable_conditions',
                maxLength: 65000,
                columnType: 'variable_conditions',
            }),
            variable_template_value: GenericColumn({
                label: 'variable_template_value',
                maxLength: 65000,
                columnType: 'variable_template_value',
            }),
            variables: JsonColumn({
                label: 'variables',
                maxLength: 4000,
                columnType: undefined,
            }),
            version: VersionColumn({
                label: 'version',
                maxLength: 65000,
            }),
        },
    },
    (_params) => {
        // Log action to validate all 15 datatypes in this part
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['56fa4224af4a47d388f95152cb764631'],
                annotation: 'Log DataTypes Group 10 - 15 datatypes',
                uuid: 'b7d456d8-c139-4d09-b06c-637d68faa898',
            },
            {
                log_level: 'info',
                log_message: `${wfa.dataPill(_params.inputs.timer, 'timer')} (Timer), ${wfa.dataPill(_params.inputs.translated, 'translated')} (Translated), ${wfa.dataPill(_params.inputs.translated_field, 'translated_field')} (translated_field), ${wfa.dataPill(_params.inputs.translated_html, 'translated_html')} (translated_html), ${wfa.dataPill(_params.inputs.translated_text, 'translated_text')} (translated_text), ${wfa.dataPill(_params.inputs.tree_code, 'tree_code')} (tree_code), ${wfa.dataPill(_params.inputs.tree_path, 'tree_path')} (tree_path), ${wfa.dataPill(_params.inputs.url, 'url')} (URL), ${wfa.dataPill(_params.inputs.user_image, 'user_image')} (user_image), ${wfa.dataPill(_params.inputs.user_input, 'user_input')} (user_input), ${wfa.dataPill(_params.inputs.user_roles, 'user_roles')} (user_roles), ${wfa.dataPill(_params.inputs.variable_conditions, 'variable_conditions')} (variable_conditions), ${wfa.dataPill(_params.inputs.variable_template_value, 'variable_template_value')} (variable_template_value), ${wfa.dataPill(_params.inputs.variables, 'glide_variables')} (Variables), ${wfa.dataPill(_params.inputs.version, 'version')} (Version)`,
            }
        )
    }
)
